export type CallDisposition =
  | 'pending'
  | 'connected'
  | 'no_answer'
  | 'voicemail'
  | 'bad_number'
  | 'do_not_call'
  | 'callback_requested';

export interface Lead {
  id: string;
  list_id: string;
  name: string;
  phone: string;
  company?: string;
  email?: string;
  notes?: string;
  cadence_step: number;
  last_attempt_at?: string | null;
  last_disposition?: CallDisposition | null;
  attempts_count: number;
  created_at: string;
  updated_at: string;
}

export interface LeadList {
  id: string;
  title: string;
  source_image_uri?: string | null;
  total_leads: number;
  completed_leads: number;
  connected_leads: number;
  created_at: string;
  updated_at: string;
}

export interface CallLog {
  id: string;
  lead_id: string;
  list_id: string;
  timestamp: string;
  duration_seconds: number;
  disposition: CallDisposition;
  note?: string;
  sms_sent: boolean;
  sms_body?: string;
}

export interface CadenceRule {
  id: string;
  step_number: number;
  condition_disposition: CallDisposition | 'any_unconnected';
  action_type: 'call_only' | 'call_and_sms' | 'sms_only';
  sms_template_id?: string | null;
  delay_hours: number;
}

export interface SMSTemplate {
  id: string;
  title: string;
  body: string; // supports {{name}}, {{company}}, {{my_name}}
}

export interface ExtractedLeadItem {
  id: string;
  name: string;
  phone: string;
  company?: string;
  notes?: string;
  isValid: boolean;
}

import * as SQLite from 'expo-sqlite';

let dbInstance: SQLite.SQLiteDatabase | null = null;

export async function getDatabase(): Promise<SQLite.SQLiteDatabase> {
  if (dbInstance) {
    return dbInstance;
  }
  dbInstance = await SQLite.openDatabaseAsync('snap_dialer.db');
  await initDatabase(dbInstance);
  return dbInstance;
}

export async function initDatabase(db: SQLite.SQLiteDatabase): Promise<void> {
  await db.execAsync(`
    PRAGMA journal_mode = WAL;
    PRAGMA foreign_keys = ON;

    CREATE TABLE IF NOT EXISTS lists (
      id TEXT PRIMARY KEY NOT NULL,
      title TEXT NOT NULL,
      source_image_uri TEXT,
      total_leads INTEGER DEFAULT 0,
      completed_leads INTEGER DEFAULT 0,
      connected_leads INTEGER DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS leads (
      id TEXT PRIMARY KEY NOT NULL,
      list_id TEXT NOT NULL,
      name TEXT NOT NULL,
      phone TEXT NOT NULL,
      company TEXT,
      email TEXT,
      notes TEXT,
      cadence_step INTEGER DEFAULT 1,
      last_attempt_at TEXT,
      last_disposition TEXT DEFAULT 'pending',
      attempts_count INTEGER DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS call_logs (
      id TEXT PRIMARY KEY NOT NULL,
      lead_id TEXT NOT NULL,
      list_id TEXT NOT NULL,
      timestamp TEXT NOT NULL,
      duration_seconds INTEGER DEFAULT 0,
      disposition TEXT NOT NULL,
      note TEXT,
      sms_sent INTEGER DEFAULT 0,
      sms_body TEXT,
      FOREIGN KEY (lead_id) REFERENCES leads(id) ON DELETE CASCADE,
      FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE CASCADE
    );

    CREATE TABLE IF NOT EXISTS cadence_rules (
      id TEXT PRIMARY KEY NOT NULL,
      step_number INTEGER NOT NULL,
      condition_disposition TEXT NOT NULL,
      action_type TEXT NOT NULL,
      sms_template_id TEXT,
      delay_hours INTEGER DEFAULT 24
    );

    CREATE TABLE IF NOT EXISTS sms_templates (
      id TEXT PRIMARY KEY NOT NULL,
      title TEXT NOT NULL,
      body TEXT NOT NULL
    );

    CREATE INDEX IF NOT EXISTS idx_leads_list_id ON leads(list_id);
    CREATE INDEX IF NOT EXISTS idx_leads_status ON leads(last_disposition);
    CREATE INDEX IF NOT EXISTS idx_call_logs_lead ON call_logs(lead_id);
  `);

  // Seed default cadence rules and SMS templates if empty
  const templateCount = await db.getFirstAsync<{ count: number }>(
    'SELECT COUNT(*) as count FROM sms_templates'
  );
  if (!templateCount || templateCount.count === 0) {
    await db.runAsync(
      `INSERT INTO sms_templates (id, title, body) VALUES 
       ('tpl_1', 'Attempt 1 Follow-up', 'Hi {{name}}, just tried reaching you. Let me know when is a good time to connect!'),
       ('tpl_2', 'Attempt 2 Quick Touch', 'Hey {{name}}, following up on my previous call regarding your inquiry. Free for a quick 2-min chat today?'),
       ('tpl_3', 'Final Follow-up', 'Hi {{name}}, wanted to check in one last time. Feel free to text me back whenever convenient.')`
    );

    await db.runAsync(
      `INSERT INTO cadence_rules (id, step_number, condition_disposition, action_type, sms_template_id, delay_hours) VALUES
       ('cad_1', 1, 'no_answer', 'call_only', NULL, 2),
       ('cad_2', 2, 'no_answer', 'call_and_sms', 'tpl_1', 24),
       ('cad_3', 3, 'no_answer', 'call_and_sms', 'tpl_2', 48)`
    );
  }
}

import { getDatabase } from './database';
import { Lead, LeadList, CallDisposition, ExtractedLeadItem } from '../types';

export class LeadsRepository {
  static async createListWithLeads(
    title: string,
    imageUri: string | null,
    leads: ExtractedLeadItem[]
  ): Promise<LeadList> {
    const db = await getDatabase();
    const listId = 'list_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7);
    const now = new Date().toISOString();

    const validLeads = leads.filter((l) => l.name.trim() && l.phone.trim());

    await db.withTransactionAsync(async () => {
      await db.runAsync(
        `INSERT INTO lists (id, title, source_image_uri, total_leads, completed_leads, connected_leads, created_at, updated_at)
         VALUES (?, ?, ?, ?, 0, 0, ?, ?)`,
        [listId, title, imageUri, validLeads.length, now, now]
      );

      for (const item of validLeads) {
        const leadId = 'lead_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7);
        await db.runAsync(
          `INSERT INTO leads (id, list_id, name, phone, company, notes, cadence_step, last_disposition, attempts_count, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, 1, 'pending', 0, ?, ?)`,
          [
            leadId,
            listId,
            item.name.trim(),
            item.phone.trim(),
            item.company || null,
            item.notes || null,
            now,
            now,
          ]
        );
      }
    });

    return {
      id: listId,
      title,
      source_image_uri: imageUri,
      total_leads: validLeads.length,
      completed_leads: 0,
      connected_leads: 0,
      created_at: now,
      updated_at: now,
    };
  }

  static async getAllLists(): Promise<LeadList[]> {
    const db = await getDatabase();
    return await db.getAllAsync<LeadList>('SELECT * FROM lists ORDER BY created_at DESC');
  }

  static async getListById(id: string): Promise<LeadList | null> {
    const db = await getDatabase();
    return await db.getFirstAsync<LeadList>('SELECT * FROM lists WHERE id = ?', [id]);
  }

  static async deleteList(id: string): Promise<void> {
    const db = await getDatabase();
    await db.runAsync('DELETE FROM lists WHERE id = ?', [id]);
  }

  static async getLeadsForList(listId: string): Promise<Lead[]> {
    const db = await getDatabase();
    return await db.getAllAsync<Lead>(
      'SELECT * FROM leads WHERE list_id = ? ORDER BY created_at ASC',
      [listId]
    );
  }

  static async getDialingQueueForList(listId: string): Promise<Lead[]> {
    const db = await getDatabase();
    // Exclude bad numbers and connected/do_not_call leads from the active power dial queue
    return await db.getAllAsync<Lead>(
      `SELECT * FROM leads 
       WHERE list_id = ? 
         AND (last_disposition IS NULL OR last_disposition IN ('pending', 'no_answer', 'voicemail'))
       ORDER BY attempts_count ASC, created_at ASC`,
      [listId]
    );
  }

  static async updateLeadDisposition(
    leadId: string,
    disposition: CallDisposition,
    note?: string
  ): Promise<void> {
    const db = await getDatabase();
    const now = new Date().toISOString();

    const lead = await db.getFirstAsync<Lead>('SELECT * FROM leads WHERE id = ?', [leadId]);
    if (!lead) return;

    const newAttempts = lead.attempts_count + 1;
    const newCadenceStep = lead.cadence_step + 1;

    await db.withTransactionAsync(async () => {
      // Update lead
      await db.runAsync(
        `UPDATE leads 
         SET last_disposition = ?, 
             attempts_count = ?, 
             cadence_step = ?, 
             last_attempt_at = ?, 
             notes = COALESCE(?, notes),
             updated_at = ?
         WHERE id = ?`,
        [disposition, newAttempts, newCadenceStep, now, note || null, now, leadId]
      );

      // Recalculate list stats
      const stats = await db.getFirstAsync<{ total: number; completed: number; connected: number }>(
        `SELECT 
           COUNT(*) as total,
           SUM(CASE WHEN last_disposition IN ('connected', 'bad_number', 'do_not_call') THEN 1 ELSE 0 END) as completed,
           SUM(CASE WHEN last_disposition = 'connected' THEN 1 ELSE 0 END) as connected
         FROM leads WHERE list_id = ?`,
        [lead.list_id]
      );

      if (stats) {
        await db.runAsync(
          `UPDATE lists 
           SET completed_leads = ?, connected_leads = ?, updated_at = ? 
           WHERE id = ?`,
          [stats.completed || 0, stats.connected || 0, now, lead.list_id]
        );
      }
    });
  }
}

import { getDatabase } from './database';
import { CallLog, CallDisposition } from '../types';

export class CallLogsRepository {
  static async logCall(params: {
    leadId: string;
    listId: string;
    durationSeconds: number;
    disposition: CallDisposition;
    note?: string;
    smsSent?: boolean;
    smsBody?: string;
  }): Promise<CallLog> {
    const db = await getDatabase();
    const id = 'log_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7);
    const now = new Date().toISOString();

    await db.runAsync(
      `INSERT INTO call_logs (id, lead_id, list_id, timestamp, duration_seconds, disposition, note, sms_sent, sms_body)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        id,
        params.leadId,
        params.listId,
        now,
        params.durationSeconds,
        params.disposition,
        params.note || null,
        params.smsSent ? 1 : 0,
        params.smsBody || null,
      ]
    );

    return {
      id,
      lead_id: params.leadId,
      list_id: params.listId,
      timestamp: now,
      duration_seconds: params.durationSeconds,
      disposition: params.disposition,
      note: params.note,
      sms_sent: !!params.smsSent,
      sms_body: params.smsBody,
    };
  }

  static async getLogsForLead(leadId: string): Promise<CallLog[]> {
    const db = await getDatabase();
    const rows = await db.getAllAsync<any>(
      'SELECT * FROM call_logs WHERE lead_id = ? ORDER BY timestamp DESC',
      [leadId]
    );
    return rows.map((r) => ({
      ...r,
      sms_sent: r.sms_sent === 1,
    }));
  }

  static async getAnalyticsSummary(): Promise<{
    totalDials: number;
    connectedCount: number;
    noAnswerCount: number;
    voicemailCount: number;
    badNumberCount: number;
    smsSentCount: number;
  }> {
    const db = await getDatabase();
    const result = await db.getFirstAsync<any>(`
      SELECT 
        COUNT(*) as totalDials,
        SUM(CASE WHEN disposition = 'connected' THEN 1 ELSE 0 END) as connectedCount,
        SUM(CASE WHEN disposition = 'no_answer' THEN 1 ELSE 0 END) as noAnswerCount,
        SUM(CASE WHEN disposition = 'voicemail' THEN 1 ELSE 0 END) as voicemailCount,
        SUM(CASE WHEN disposition = 'bad_number' THEN 1 ELSE 0 END) as badNumberCount,
        SUM(CASE WHEN sms_sent = 1 THEN 1 ELSE 0 END) as smsSentCount
      FROM call_logs
    `);

    return {
      totalDials: result?.totalDials || 0,
      connectedCount: result?.connectedCount || 0,
      noAnswerCount: result?.noAnswerCount || 0,
      voicemailCount: result?.voicemailCount || 0,
      badNumberCount: result?.badNumberCount || 0,
      smsSentCount: result?.smsSentCount || 0,
    };
  }
}

