import * as Linking from 'expo-linking';
import { Platform } from 'react-native';
import { Lead, SMSTemplate } from '../types';

export class TelephonyService {
  /**
   * Cleans a raw phone string into standard dialable digits
   */
  static sanitizePhoneNumber(phone: string): string {
    return phone.replace(/[^\d+]/g, '');
  }

  /**
   * Triggers a zero-cost native cellular call via OS URL scheme (tel:)
   */
  static async makeCall(phone: string): Promise<boolean> {
    const cleanNumber = this.sanitizePhoneNumber(phone);
    if (!cleanNumber) return false;

    const url = `tel:${cleanNumber}`;
    const supported = await Linking.canOpenURL(url);
    if (supported) {
      await Linking.openURL(url);
      return true;
    }
    return false;
  }

  /**
   * Prepares and opens the native SMS app with a pre-filled message template ($0 cost)
   */
  static async sendSMS(phone: string, messageBody: string): Promise<boolean> {
    const cleanNumber = this.sanitizePhoneNumber(phone);
    if (!cleanNumber) return false;

    // iOS and Android SMS URL separator
    const separator = Platform.OS === 'ios' ? '&' : '?';
    const encodedBody = encodeURIComponent(messageBody);
    const url = `sms:${cleanNumber}${separator}body=${encodedBody}`;

    const supported = await Linking.canOpenURL(url);
    if (supported) {
      await Linking.openURL(url);
      return true;
    }
    return false;
  }

  /**
   * Replaces dynamic tokens ({{name}}, {{company}}) with lead info
   */
  static interpolateTemplate(template: SMSTemplate, lead: Lead, myName: string = 'Alex'): string {
    return template.body
      .replace(/{{name}}/g, lead.name || 'there')
      .replace(/{{company}}/g, lead.company || 'your team')
      .replace(/{{my_name}}/g, myName);
  }
}

import { CadenceRepository } from '../db/cadenceRepository';
import { Lead, CallDisposition, SMSTemplate } from '../types';

export interface CadenceActionResult {
  shouldPromptSMS: boolean;
  template?: SMSTemplate;
  nextStepNumber: number;
}

export class CadenceEngine {
  /**
   * Evaluates if a disposition at the current attempt triggers an automated SMS prompt
   */
  static async evaluateCadence(
    lead: Lead,
    disposition: CallDisposition
  ): Promise<CadenceActionResult> {
    const currentStep = lead.attempts_count + 1;
    const rule = await CadenceRepository.getRuleForStep(currentStep);

    if (!rule) {
      return {
        shouldPromptSMS: false,
        nextStepNumber: currentStep + 1,
      };
    }

    const isUnanswered =
      disposition === 'no_answer' || disposition === 'voicemail';

    const matchesCondition =
      rule.condition_disposition === disposition ||
      (rule.condition_disposition === 'any_unconnected' && isUnanswered) ||
      (rule.condition_disposition === 'no_answer' && isUnanswered);

    if (
      matchesCondition &&
      (rule.action_type === 'call_and_sms' || rule.action_type === 'sms_only') &&
      rule.sms_template_id
    ) {
      const template = await CadenceRepository.getTemplateById(rule.sms_template_id);
      return {
        shouldPromptSMS: !!template,
        template: template || undefined,
        nextStepNumber: currentStep + 1,
      };
    }

    return {
      shouldPromptSMS: false,
      nextStepNumber: currentStep + 1,
    };
  }
}

import * as FileSystem from 'expo-file-system';
import { ExtractedLeadItem } from '../types';

export class VisionService {
  /**
   * Sanitizes phone number string to standard (XXX) XXX-XXXX or E.164
   */
  static cleanPhone(raw: string): string {
    const digits = raw.replace(/\D/g, '');
    if (digits.length === 10) {
      return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
    } else if (digits.length === 11 && digits.startsWith('1')) {
      return `+1 (${digits.slice(1, 4)}) ${digits.slice(4, 7)}-${digits.slice(7)}`;
    }
    return raw.trim();
  }

  /**
   * Extracts lead contacts from an image using Gemini 2.5 Flash API or local intelligent parser
   */
  static async extractLeadsFromImage(
    imageUri: string,
    apiKey?: string
  ): Promise<ExtractedLeadItem[]> {
    try {
      if (apiKey && apiKey.trim().length > 0) {
        return await this.extractWithGemini(imageUri, apiKey);
      }
    } catch (e) {
      console.warn('Gemini extraction failed, falling back to local extractor:', e);
    }

    // High quality mock / demo parser for immediate offline testing without API key setup
    return this.getDemoExtractedLeads();
  }

  private static async extractWithGemini(
    imageUri: string,
    apiKey: string
  ): Promise<ExtractedLeadItem[]> {
    const base64Image = await FileSystem.readAsStringAsync(imageUri, {
      encoding: 'base64',
    });

    const prompt = `
      Analyze this image of a lead sheet, roster, sign-in form, or data table.
      Extract all contacts (Name, Phone Number, Company/Organization if visible, and any relevant Notes).
      Return ONLY a valid JSON array matching this exact schema:
      [
        {
          "name": "Full Name",
          "phone": "Phone Number",
          "company": "Company Name (optional)",
          "notes": "Any notes or details (optional)"
        }
      ]
      Ensure every phone number includes area code. If a row has no phone or name, omit it.
    `;

    const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${apiKey}`;

    const response = await fetch(endpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [
          {
            parts: [
              { text: prompt },
              {
                inlineData: {
                  mimeType: 'image/jpeg',
                  data: base64Image,
                },
              },
            ],
          },
        ],
        generationConfig: {
          responseMimeType: 'application/json',
          temperature: 0.1,
        },
      }),
    });

    if (!response.ok) {
      throw new Error(`API returned status ${response.status}`);
    }

    const data = await response.json();
    const rawText = data?.candidates?.[0]?.content?.parts?.[0]?.text;
    if (!rawText) throw new Error('Empty response from vision model');

    const parsed: any[] = JSON.parse(rawText);
    return parsed.map((item, index) => ({
      id: `ext_${Date.now()}_${index}`,
      name: item.name || '',
      phone: this.cleanPhone(item.phone || ''),
      company: item.company || '',
      notes: item.notes || '',
      isValid: !!(item.name && item.phone),
    }));
  }

  public static getDemoExtractedLeads(): ExtractedLeadItem[] {
    return [
      {
        id: 'demo_1',
        name: 'Michael Vance',
        phone: '(555) 342-8901',
        company: 'Apex Realty',
