export default function ListsScreen({ navigation }: any) {
  const [lists, setLists] = useState<LeadList[]>([]);
  const [loading, setLoading] = useState<boolean>(true);

  const loadLists = async () => {
    try {
      const data = await LeadsRepository.getAllLists();
      setLists(data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useFocusEffect(
    useCallback(() => {
      loadLists();
    }, [])
  );

  const handleDelete = (id: string, title: string) => {
    Alert.alert('Delete List', `Are you sure you want to delete "${title}"?`, [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Delete',
        style: 'destructive',
        onPress: async () => {
          await LeadsRepository.deleteList(id);
          loadLists();
        },
      },
    ]);
  };

  const renderItem = ({ item }: { item: LeadList }) => {
    const progress = item.total_leads > 0 ? (item.completed_leads / item.total_leads) * 100 : 0;

    return (
