          >
            <BarChart3 size={22} color="#F8FAFC" />
          </TouchableOpacity>
          <TouchableOpacity
            style={styles.iconButton}
            onPress={() => navigation.navigate('CadenceSettings')}
          >
            <Settings size={22} color="#F8FAFC" />
          </TouchableOpacity>
        </View>
      </View>

      {/* Main Content */}
      {loading ? (
        <View style={styles.centerContainer}>
          <ActivityIndicator size="large" color="#3B82F6" />
        </View>
      ) : lists.length === 0 ? (
        <View style={styles.emptyContainer}>
          <Camera size={56} color="#475569" />
          <Text style={styles.emptyTitle}>No Lead Lists Yet</Text>
          <Text style={styles.emptyDesc}>
            Take a photo of any paper lead sheet, sign-in roster, or data sheet to start your first power dialing session.
          </Text>
          <TouchableOpacity
            style={styles.primaryButton}
            onPress={() => navigation.navigate('ScanSheet')}
          >
            <Camera size={20} color="#FFFFFF" />
            <Text style={styles.primaryButtonText}>Snap Lead Sheet</Text>
          </TouchableOpacity>
        </View>
      ) : (
        <FlatList
          data={lists}
          keyExtractor={(item) => item.id}
          renderItem={renderItem}
          contentContainerStyle={styles.listContent}
